#!/usr/bin/env python3
"""Extract W61 base Kill Clip from pinned official sources, without network IO.

Writes only the W61 resource and art/weapons/w61/references/*.json.
--verify reads every pinned source and compares all generated bytes; no writes.
Raw article/search captures remain private in /tmp/destiny-weapons-w61.
"""
import sys
sys.dont_write_bytecode = True

import argparse
import hashlib
import html
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = "scripts/extract_kill_clip_w61.py"
REF = "art/weapons/w61/references/"
TARGET = "src/main/resources/destiny/weapons/w61-kill-clip.json"
VERSION = "245114.26.10.13.2000-1-bnet.66137"
SUFFIX = "e677f6ea-2a1e-48d4-a8c8-700a39a62585.json"
BASE, ENHANCED, ALH = 1015611457, 2923251173, 3300816228
TRAIT_CATEGORY = 4241085061
BUNGIE = "https://www.bungie.net"
PATCH_URL = BUNGIE + "/7/en/News/article/destiny2_update_630"
BASE_URL = "https://www.light.gg/db/de/items/1015611457/kill-clip/?_=707"
ENHANCED_URL = "https://www.light.gg/db/items/2923251173/kill-clip/?_=553"
DODGE_URL = "https://www.light.gg/db/items/426473316/marksmans-dodge/"
ALH_URL = "https://d2.destinygamewiki.com/wiki/Auto-Loading_Holster"
PINS = {
    "selected": "5d27e02c073de0b348ba15312643cc7029a044ed5617a801dbfed2d86cd8f9a1",
    "w40Provenance": "281bba3a34ec308b9f7b64d09c7d2b012925bcee1a4b02fac12a99ca9d730d42",
    "inventory": "b47bba01acdcb7c08e28726647864efefea8ffe73a7098d1c725c7118545b94c",
    "plugSets": "8e3e4625cefca0fcec28524b2de7e65020fe1a7111fa38aa079ad4974cd67959",
    "manifest": "bf6fd27036df7d87a2ea03d0e688b7c0b7cc76a9c3ff783ad14b3f14f4d07dce",
    "patch": "793955bf6392b2789f687f65b1c8c79540f3789b249e39b3351b73ffe7e6dc2a",
    "measurements": "f993ba340690284679c197bf90703e22165ce5ac9e04a46a6ef998379f1e9e2c",
    "dodgeResearch": "25c8d9ee5e485fce22881a79f13835507f4c2cd0422aa1b1b4e93895452198e2",
    "reloadResearch": "acde9bc1fb1ff36f45d0bbb438c2294deff9d4e2f85dad49ed44d5e87d2440ff",
}
EXPECTED_RANDOM = {
    ("duke_mk_44", 2112909414, 4, 3815727680),
    ("gnawing_hunger", 821154603, 4, 594510568),
    ("bygones", 2712244741, 3, 1760176771),
    ("chattering_bone", 568515759, 3, 216806616),
    ("blast_furnace", 3843477312, 4, 169306153),
    ("claws_of_the_wolf", 1280933460, 4, 753756428),
    ("lonesome", 2199171672, 4, 167712635),
    ("dead_man_walking_xx7463", 3751622019, 4, 1210839935),
    ("apostate", 2164448701, 4, 2826016044),
    ("dust_rock_blues", 636912560, 3, 3511609070),
    ("canis_major", 2066434718, 4, 2791121719),
    ("bad_omens", 991314988, 4, 2955928741),
}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def encoded(value):
    return (json.dumps(value, indent=2, ensure_ascii=False) + "\n").encode()


def normalize(value):
    return " ".join(html.unescape(re.sub(r"<[^>]*>", " ", value)).split())


def evidence_block(source, url, phrases):
    """Bind each assertion to one result's URL, rather than the whole search."""
    texts = "\n".join(c.get("text", "") for c in source["content"])
    blocks = texts.split("--------------------------------------------------------------------------------")
    matches = [b for b in blocks if "(" + url + ")" in b and all(p in b for p in phrases)]
    require(len(matches) == 1, "Missing or ambiguous community evidence: " + url)


def extract(args):
    root = args.root
    paths = {
        "selected": root / "art/weapons/w40/definitions.json",
        "w40Provenance": root / "art/weapons/w40/provenance.json",
        "inventory": args.inventory,
        "plugSets": args.shared_sources_dir / "bungie-plugsets.json",
        "manifest": args.shared_sources_dir / "manifest.json",
        "patch": args.sources_dir / "destiny2_update_630-response.json",
        "measurements": args.sources_dir / "exact-search.json",
        "dodgeResearch": args.sources_dir / "reload-search.json",
        "reloadResearch": args.sources_dir / "edge-search.json",
    }
    sources, pins = {}, {}
    for key, path in paths.items():
        raw = path.read_bytes()
        require(digest(raw) == PINS[key], "Source SHA256 mismatch: " + key)
        sources[key] = json.loads(raw)
        pins[key] = {"path": str(path.relative_to(root)) if path.is_relative_to(root)
                     else str(path), "sha256": PINS[key], "bytes": len(raw)}

    response = sources["manifest"]
    require(response["ErrorCode"] == 1, "Manifest API response failed")
    manifest = response["Response"]
    require(manifest["version"] == VERSION, "Manifest version mismatch")
    components = manifest["jsonWorldComponentContentPaths"]["en"]
    inventory_path = "/common/destiny2_content/json/en/DestinyInventoryItemDefinition-" + SUFFIX
    plugsets_path = "/common/destiny2_content/json/en/DestinyPlugSetDefinition-" + SUFFIX
    require(components["DestinyInventoryItemDefinition"] == inventory_path
            and components["DestinyPlugSetDefinition"] == plugsets_path,
            "Inventory and plug sets must belong to the same pinned manifest")
    w40 = sources["w40Provenance"]
    require(w40["manifest"] == {"version": VERSION, "path": inventory_path}
            and w40["cachedInventorySha256"] == PINS["inventory"]
            and w40["source"] == BUNGIE + inventory_path, "W40 provenance mismatch")
    selected, inventory, plugsets = sources["selected"], sources["inventory"], sources["plugSets"]
    require(len(selected) == len({w["id"] for w in selected})
            == len({w["bungieHash"] for w in selected}) == 63,
            "Expected the exact 63 unique selected hashes")

    definitions = []
    for perk_hash, kind in [(BASE, "Trait"), (ENHANCED, "Enhanced Trait")]:
        perk = inventory[str(perk_hash)]
        require(perk["hash"] == perk_hash and perk["displayProperties"]["name"] == "Kill Clip"
                and perk["itemTypeDisplayName"] == kind and perk["itemType"] == 19
                and not perk["redacted"] and not perk["blacklisted"]
                and not perk["plug"]["isDummyPlug"], "Not the genuine Kill Clip definition")
        definitions.append({"hash": perk_hash, "name": perk["displayProperties"]["name"],
                            "itemTypeDisplayName": kind,
                            "description": perk["displayProperties"]["description"]})

    rows, proofs, direct_options, enhanced_options, alh_rows = [], [], [], [], []
    random_keys = set()
    for weapon in selected:
        item = inventory[str(weapon["bungieHash"])]
        require(item["hash"] == weapon["bungieHash"] and item["itemType"] == 3
                and not item["redacted"] and not item["blacklisted"], "Invalid selected weapon")
        sockets = item.get("sockets", {})
        trait_indexes = {i for cat in sockets.get("socketCategories", [])
                         if cat["socketCategoryHash"] == TRAIT_CATEGORY for i in cat["socketIndexes"]}
        for index, socket in enumerate(sockets.get("socketEntries", [])):
            direct = {socket["singleInitialItemHash"],
                      *[p["plugItemHash"] for p in socket.get("reusablePlugItems", [])]}
            if BASE in direct:
                direct_options.append({"id": weapon["id"], "socket": index,
                                       "initialPerk": socket["singleInitialItemHash"] == BASE})
            if ENHANCED in direct:
                enhanced_options.append({"id": weapon["id"], "socket": index, "source": "direct"})
            for field in ("randomizedPlugSetHash", "reusablePlugSetHash"):
                set_hash = socket.get(field)
                if not set_hash:
                    continue
                pool = plugsets[str(set_hash)]  # Missing referenced source fails closed.
                require(pool["hash"] == set_hash and not pool["redacted"]
                        and not pool["blacklisted"], "Invalid referenced plug set")
                entries = pool.get("reusablePlugItems", [])
                if any(p["plugItemHash"] == ENHANCED for p in entries):
                    enhanced_options.append({"id": weapon["id"], "socket": index, "source": field})
                if field != "randomizedPlugSetHash":
                    continue
                for perk_hash in (BASE, ALH):
                    matches = [p for p in entries if p["plugItemHash"] == perk_hash
                               and p.get("currentlyCanRoll") is True]
                    if not matches:
                        continue
                    require(len(matches) == 1 and index in trait_indexes and not pool["isFakePlugSet"],
                            "Perk is not in a real randomized trait pool")
                    require(weapon["exotic"] is False and item["inventory"]["tierType"] != 6
                            and item["itemTypeDisplayName"] != "Sword",
                            "Exotics and swords are outside W61")
                    row = {"id": weapon["id"], "hash": item["hash"], "socket": index,
                           "perkHash": perk_hash, "plugSetHash": set_hash}
                    if perk_hash == ALH:
                        alh_rows.append(row)
                        continue
                    rows.append(row)
                    random_keys.add((row["id"], row["hash"], index, set_hash))
                    proofs.append({**row, "selection": "randomized", "socketCategoryHash": TRAIT_CATEGORY,
                                   "socketEntry": socket, "plugSetField": field,
                                   "isFakePlugSet": pool["isFakePlugSet"], "plugSetItem": matches[0]})

            # Explicit fixed trait exception, never inferred from a fake pool alone.
            if (weapon["id"], item["hash"], index) == ("antiope_d", 566976653, 3):
                require(index in trait_indexes and socket["singleInitialItemHash"] == BASE
                        and not socket.get("randomizedPlugSetHash")
                        and socket["reusablePlugSetHash"] == 669
                        and socket["reusablePlugItems"] == []
                        and weapon["exotic"] is False and item["inventory"]["tierType"] == 5
                        and item["itemTypeDisplayName"] == "Submachine Gun", "Fixed Antiope-D proof changed")
                pool = plugsets["669"]
                require(pool["hash"] == 669 and pool["isFakePlugSet"] is True
                        and not pool["redacted"] and not pool["blacklisted"]
                        and len(pool["reusablePlugItems"]) == 1
                        and pool["reusablePlugItems"][0]["plugItemHash"] == BASE,
                        "Fixed Antiope-D reusable set changed")
                row = {"id": "antiope_d", "hash": 566976653, "socket": 3,
                       "perkHash": BASE, "plugSetHash": 669}
                rows.append(row)
                proofs.append({**row, "selection": "fixedInitialTrait", "socketCategoryHash": TRAIT_CATEGORY,
                               "socketEntry": socket, "plugSetField": "reusablePlugSetHash",
                               "isFakePlugSet": True, "plugSetItem": pool["reusablePlugItems"][0],
                               "reason": "The selected item's own singleInitialItemHash proves its fixed trait. Set 669 is a real referenced identifier but a fake plug set, not randomized roll evidence."})
    require(random_keys == EXPECTED_RANDOM and len(rows) == 13
            and len({(r["id"], r["socket"]) for r in rows}) == 13,
            "Expected exactly 12 randomized rows and one fixed Antiope-D row")
    require(not enhanced_options, "Selected enhanced options changed; re-review scope")
    require(len(alh_rows) == 18, "W60 matching-manifest cross-check changed")

    article_response = sources["patch"]
    require(article_response["count"] == len(article_response["entries"]) == 1, "Ambiguous official article")
    entry = article_response["entries"][0]
    require(entry["url"]["hosted_url"] == "/destiny2_update_630"
            and entry["title"] == "Destiny 2 Update 6.3.0"
            and entry["date"] == "2022-12-06T16:30:00.000Z" and entry["locale"] == "en-us",
            "Official article identity mismatch")
    article_text = normalize(entry["html_content"])
    heading = "Tunnel Vision + Kill Clip"
    require(article_text.count(heading) == 1, "Ambiguous official perk section")
    section = article_text.split(heading, 1)[1].split("Redirection", 1)[0].strip()
    require(section == "The duration of these buffs can now be refreshed if activated while already active. "
            "Reduced damage bonus from Kill Clip from 33% to 25%.", "Official mechanics text changed")

    evidence_block(sources["measurements"], BASE_URL,
                   ["API ID: 1015611457", "Community Research",
                    "Finishing a reload within 3.6 seconds of a kill grants 25% increased damage for 5 seconds.",
                    "Stowing the weapon removes the buff."])
    evidence_block(sources["measurements"], ENHANCED_URL,
                   ["API ID: 2923251173", "Enhanced Trait", "3.6 seconds", "5.5 seconds"])
    evidence_block(sources["dodgeResearch"], DODGE_URL,
                   ["Counts as a manual reload and will activate reload-triggered perks such as Kill Clip."])
    evidence_block(sources["reloadResearch"], ALH_URL,
                   ["Auto-Loading Holster does not trigger on-reload effects"])

    dual = [{"id": k["id"], "hash": k["hash"], "killClipSocket": k["socket"],
             "killClipPlugSetHash": k["plugSetHash"], "holsterSocket": a["socket"],
             "holsterPlugSetHash": a["plugSetHash"]}
            for k in rows for a in alh_rows if k["hash"] == a["hash"] and k["socket"] != a["socket"]]
    require({d["id"] for d in dual} == {"gnawing_hunger", "dust_rock_blues", "bad_omens"},
            "Dual socket candidates changed")
    coverage = {r["id"] for r in rows}
    mechanics = {
        "stage": "W61", "baseHash": BASE, "enhancedHashExcluded": ENHANCED,
        "ticksPerSecond": 20, "killWindowSeconds": 3.6, "killWindowTicks": 72,
        "durationSeconds": 5, "durationTicks": 100, "multiplier": 1.25,
        "primaryChange": {"url": PATCH_URL, "publisher": "Bungie", "primary": True,
                          "title": entry["title"], "publishedAt": entry["date"], "deliveryUid": entry["uid"],
                          "bodyField": "html_content", "heading": heading,
                          "damageExcerpt": "Reduced damage bonus from Kill Clip from 33% to 25%.",
                          "refreshExcerpt": "refreshed if activated while already active.",
                          "supports": ["25 percent damage bonus", "A qualifying activation can refresh an active buff"],
                          "doesNotEstablish": ["Absolute timing", "Stow behavior", "Reload event classification"]},
        "communityMeasurements": {"url": BASE_URL, "publisher": "light.gg", "primary": False,
                                  "section": "Community Research", "searchCapture": "exact-search.json",
                                  "windowExcerpt": "Finishing a reload within 3.6 seconds of a kill",
                                  "durationExcerpt": "5 seconds", "stowExcerpt": "Stowing the weapon removes the buff.",
                                  "retrieval": "Search-index body of the exact base hash's German page; research text is English. Direct English page fetch failed with HTTP 402 in the web tool."},
        "enhancedComparison": {"url": ENHANCED_URL, "primary": False, "durationSeconds": 5.5,
                               "killWindowSeconds": 3.6, "implemented": False,
                               "warning": "5.5 seconds belongs to enhanced hash 2923251173, not base hash 1015611457."},
        "reloadRules": {
            "windowEvent": "Reload completion, measured from the weapon kill; starting a reload within 72 ticks is insufficient if completion is late.",
            "manualReload": {"activates": True, "evidence": "Official perk description plus community completion measurement"},
            "marksmanDodge": {"activatesReloadPerks": True, "primary": False, "url": DODGE_URL,
                              "excerpt": "Counts as a manual reload and will activate reload-triggered perks such as Kill Clip.",
                              "integrationPolicy": "Call the activation hook at actual ammo transfer, with the same kill deadline; a dodge with no reload must not synthesize a reload event.",
                              "policyBoundary": "The source classifies the dodge; it does not independently test full-magazine, zero-reserve or zero-transfer cases."},
            "autoLoadingHolster": {"activatesReloadPerks": False, "primary": False, "url": ALH_URL,
                                   "excerpt": "Auto-Loading Holster does not trigger on-reload effects",
                                   "limitation": "Community wiki note, not an official Bungie assertion; the page's separate 3-second duration is not used."},
            "shotgunFirstShell": {"verified": False,
                                  "integrationPolicy": "Use the first successful shell insertion as the reload event and consume that kill eligibility once per reload sequence.",
                                  "policyBoundary": "Suggested adaptation to this project's progressive reload events. Retrieved sources do not settle first-shell versus final-shell activation or repeated-shell refresh; not verified Destiny behavior."},
        },
        "stowRules": {"activeBuff": "remove", "activeBuffVerifiedByCommunity": True,
                      "pendingKillWindow": "unresolved",
                      "suggestedIntegrationPolicy": "Clear active buff and pending eligibility on stow; do not restore either on draw.",
                      "policyBoundary": "Only active-buff removal is evidenced. Clearing the pending kill window is a conservative integration choice, not a sourced mechanic."},
        "refreshRules": {"qualifyingKillAndReloadWhileActive": "Refresh active duration to the base 100 ticks from completion.",
                         "primarySupportsRefresh": True,
                         "integrationPolicy": "Consume the pending kill on activation; a reload with no new qualifying kill must not refresh.",
                         "policyBoundary": "One-time consumption, tick endpoint inclusion, and repeated reloads from the same kill are not independently established by the retrieved sources."},
        "damageBoundary": "Community research excludes splash/explosive damage belonging to other perks. This does not prove that a rocket's own blast is excluded. Projectile snapshot timing is not established here.",
        "limitations": ["Absolute times and stow cancellation are community measurements, not numeric Bungie manifest fields.",
                        "20 ticks per second is the project's conversion; Destiny tick-boundary inclusivity is not measured.",
                        "No live gameplay tests or exhaustive audit of later patches was performed.",
                        "Do not promote the explicitly labeled integration policies to verified Destiny facts."],
    }
    pools = {
        "stage": "W61", "selectedCount": 63, "supportedCount": len(coverage), "poolRows": len(rows),
        "randomizedPoolRows": 12, "fixedDirectRows": 1, "perkDefinitions": definitions,
        "policy": "Base hash only, selected item hashes only, zero-based trait socket indexes. Randomized selection requires currentlyCanRoll=true in a non-fake randomizedPlugSetHash. Weights are not availability evidence. The single documented fixed exception is Antiope-D's own initial trait; its plugSetHash=669 is a fake reusable set and must never be described as a random pool.",
        "weapons": proofs, "directSocketOptions": direct_options, "enhancedSelectedOptions": enhanced_options,
        "unsupportedSelectedIds": [w["id"] for w in selected if w["id"] not in coverage],
        "dualHolsterKillClipCandidates": dual,
        "projectileTestCandidate": {"id": "bad_omens", "hash": 991314988, "weaponType": "Rocket Launcher",
                                    "killClipSocket": 4, "killClipPlugSetHash": 2955928741,
                                    "holsterSocket": 3, "holsterPlugSetHash": 457210958},
        "limitations": ["Pool membership permits an optional roll; it does not equip the perk on every copy.",
                        "A different socket may contribute another row for the same weapon; consumers must key by id and socket, not id alone.",
                        "No enhanced, exotic, sword, catalyst, or same-name reprised item is inferred."],
    }
    provenance = {
        "stage": "W61", "manifestVersion": VERSION,
        "manifestEndpoint": BUNGIE + "/Platform/Destiny2/Manifest/",
        "inventoryUrl": BUNGIE + inventory_path, "plugSetsUrl": BUNGIE + plugsets_path,
        "sourceHashes": pins, "generator": SCRIPT, "generatorSha256": digest((root / SCRIPT).read_bytes()),
        "articleRetrieval": {"deliveryEndpoint": "https://cdn.contentstack.io/v3/content_types/news_article/entries",
                             "environment": "live", "locale": "en-us", "selector": "url.hosted_url=/destiny2_update_630; limit=2; count=1",
                             "credentialsOrigin": "Official Bungie Settings cached privately for W57; no headers or credentials published."},
        "communityRetrieval": "Pinned raw web tool responses retrieved 2026-10-24. Each asserted mechanic is matched within one URL-bound result block. These are search captures, not direct light.gg HTTP bodies.",
        "sourceBoundary": "Official inventory and plug sets establish membership. Official 6.3.0 establishes 25 percent and refresh. Community measurements establish 3.6-second completion window, 5-second base duration, stow removal and reload classification. Unsettled edge cases remain labeled policies or unresolved.",
        "reproduce": "rtk proxy python3 scripts/extract_kill_clip_w61.py --verify",
        "privateSources": "Full official documents and search captures are outside the repository under /tmp. Verification requires these pinned files, performs no network IO, never updates pins and writes nothing.",
    }
    resource = {"stage": "W61", "perk": {"id": "kill_clip", "hash": BASE,
                "killWindowTicks": 72, "durationTicks": 100, "multiplier": 1.25,
                "timingSource": REF + "mechanics.json"}, "weapons": rows}
    return {TARGET: resource, REF + "mechanics.json": mechanics,
            REF + "socket-pools.json": pools, REF + "provenance.json": provenance}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--verify", action="store_true", help="Read-only, byte-exact offline reproduction; missing/changed inputs fail")
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--inventory", type=Path, default=Path("/tmp/destiny-weapons-w30/bungie-items.json"))
    parser.add_argument("--shared-sources-dir", type=Path, default=Path("/tmp/destiny-weapons-w60"))
    parser.add_argument("--sources-dir", type=Path, default=Path("/tmp/destiny-weapons-w61"))
    args = parser.parse_args()
    try:
        outputs = extract(args)
        if args.verify:
            for name, value in outputs.items():
                require((args.root / name).read_bytes() == encoded(value), "Generated output differs: " + name)
        else:
            for name, value in outputs.items():
                path = args.root / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(encoded(value))
        print(("VERIFIED" if args.verify else "GENERATED")
              + ": W61, 63 selected, 13 supported weapons/rows (12 randomized + 1 fixed); 72-tick kill window, 100-tick buff, 1.25x; 0 enhanced.")
        print("Bad Omens: Kill Clip socket 4, ALH socket 3. Shotgun first-shell and pending-window stow behavior are unverified integration policies.")
    except (OSError, ValueError, KeyError, TypeError) as error:
        print("W61 verification failed: " + str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
